def calc(expr: str) -> int | str:
    s = expr
    n = len(s)
    i = 0

    def skip() -> None:
        nonlocal i
        while i < n and s[i] == " ":
            i += 1

    def trunc_div(a: int, b: int) -> int:
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_add():
        left = parse_mul()
        while True:
            skip()
            if i >= n or s[i] not in "+-":
                return left
            op = s[i]
            i += 1
            right = parse_mul()
            if isinstance(left, str) or isinstance(right, str):
                left = "error"
            elif op == "+":
                left = left + right
            else:
                left = left - right

    def parse_mul():
        left = parse_unary()
        while True:
            skip()
            if i >= n or s[i] not in "*/%":
                return left
            op = s[i]
            i += 1
            right = parse_unary()
            if isinstance(left, str) or isinstance(right, str):
                left = "error"
            elif op == "*":
                left = left * right
            elif right == 0:
                left = "error"
            else:
                q = trunc_div(left, right)
                left = q if op == "/" else left - right * q

    def parse_unary():
        skip()
        if i < n and s[i] == "-":
            i += 1
            val = parse_unary()
            if isinstance(val, str):
                return val
            return -val
        return parse_power()

    def parse_power():
        base = parse_primary()
        skip()
        if i >= n or s[i] != "^":
            return base
        i += 1
        exp = parse_unary()
        if isinstance(base, str) or isinstance(exp, str):
            return "error"
        if exp < 0:
            return "error"
        return pow(base, exp)

    def parse_primary():
        skip()
        if s[i] == "(":
            i += 1
            val = parse_add()
            skip()
            i += 1  # ')'
            return val
        start = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[start:i])

    return parse_add()
